		if ((vBorderMask & 1) != 0) distanceToWall = min(distanceToWall, vEdgeDistances.x);
		if ((vBorderMask & 2) != 0) distanceToWall = min(distanceToWall, vEdgeDistances.y);
		if ((vBorderMask & 4) != 0) distanceToWall = min(distanceToWall, vEdgeDistances.z);
		if ((vBorderMask & 8) != 0) distanceToWall = min(distanceToWall, vEdgeDistances.w);
